// Node's own resolution rule sends this require to vt2-init-lib's OWN
// node_modules, not the top-level one: a package's private tree is
// searched before its parents'. The two installs are identical in name,
// version and vulnerable export name, and distinguishable only by path.
const dep = require("vt2-vuln-lib");

// A private helper that exists only to share the vulnerable export's
// spelling (RWF-011). Nothing publishes it, nothing calls it, and it is
// declared BEFORE everything real -- so both a same-file bare-name search
// and a "first function in the file" heuristic land here.
function dangerousOp(input) {
  return "decoy:" + input;
}

// The branch that reaches the vulnerable package. Nothing in this file
// calls it: the ONLY way it ever runs is by being this module's exported
// value.
function fastPath(input) {
  return dep.dangerousOp(input);
}

// The branch that does not.
function slowPath(input) {
  return "slow:" + input;
}

// A resolvable local callable whose entire body is a single unconditional
// throw. RWF-016's callee, unchanged and not widened by this case.
function bail() {
  throw new Error("fast mode is not supported by this build");
}

// Harmless local callables that RETURN NORMALLY. `before` and `after`
// exist so that ARGUMENT EVALUATION ORDER is exercised rather than
// assumed; `install` is the callee whose arguments are being built.
function before() {
  return "before";
}

function after() {
  return "after";
}

function install(a, b, c) {
  return [a, b, c];
}

// A callable that throws on ONE path and returns on another. It is NOT
// definitely abrupt -- a caller can observe a normal completion -- so no
// expression containing it may be treated as a cutoff, however necessarily
// evaluated that expression is. This is the P0-B / RWF-027 boundary,
// deliberately present and deliberately not closed here.
function maybe(flag) {
  if (flag) {
    throw new Error("sometimes");
  }
  return "returned";
}

// An ALIAS and a MEMBER holder for `bail`. Calling either really does
// throw at runtime, but proving that means resolving a callee this
// analyzer does not resolve -- the P0-E / RWF-028 boundary, likewise
// present and likewise not closed here.
const alias = bail;
const holder = { bail };

// A conditional guard the analyzer cannot evaluate.
const FLAG = process.env.VT2_CONDITION === "yes";

// ===========================================================================
// THE CONDITIONAL AND DEFERRED DECOYS. Every one of these mentions `bail`,
// every one of them runs at module scope or is written at module scope, and
// NOT ONE of them ends module evaluation. An analyzer that fires on "an
// abrupt call appears somewhere under this statement" cuts the module off
// here -- right by accident about this file, wrong about every module that
// legitimately guards a throwing helper.
// ===========================================================================

// Short-circuit: the RIGHT operand of a logical operator runs only for some
// values of the left one, and `FLAG` is a runtime value.
const guarded = FLAG && bail();

// Both arms of a conditional expression. Neither is required, and joining
// two abrupt arms into one proof is multi-path reasoning this analyzer does
// not do.
const chosen = FLAG ? bail() : before();

// Logical assignment: the RHS is evaluated only when the target's current
// value says to.
let mode = "preset";
mode ||= bail();

// A loop UPDATE expression, which is not reached until an iteration has
// completed -- and this body breaks on its first pass, so it never runs at
// all. Its TEST, by contrast, would be a genuine cutoff.
for (let i = 0; i < 3; bail()) {
  break;
}

// A `do`/`while` condition, reached only after the body completes.
do {
  break;
} while (bail());

// Deferred contexts: writing a function evaluates nothing.
const callback = () => install(bail(), before(), after());
function withDefault(x = bail()) {
  return x;
}
class Holder {
  // An INSTANCE field, evaluated per-CONSTRUCTION. Nothing constructs one
  // at module scope. Its STATIC counterpart would be a genuine cutoff.
  field = bail();
  probe() {
    return bail();
  }
}
function configure() {
  // A same-name shadow, inside a function nothing calls at module scope.
  // Real JS lexical scoping never resolves the module-scope calls above to
  // this one.
  function bail() {
    return "safe";
  }
  return install(bail(), before(), after());
}

// A callee this analyzer cannot prove abrupt, in a position that IS
// necessarily evaluated, at module scope, on every load. The POSITION is
// sound and RWF-026 models it; the CALLEE is not proven, because `maybe`
// returns on one path -- so no cutoff may be claimed. This is the P0-B /
// RWF-027 boundary standing in the strongest place it can stand.
const viaMaybe = install(before(), maybe(FLAG), after());

// The ALIAS, MEMBER and `new` forms of the same idea. They are written
// inside a function nothing calls at module scope, and they have to be:
// each of these calls really does throw under real `node`, so hoisting
// them to module scope would make this module throw on EVERY load and
// destroy the two-worlds shape the case depends on. That they would be a
// genuine cutoff if this analyzer resolved their callees is precisely the
// P0-E / RWF-028 boundary -- open, recorded, and not to be closed from
// here by an expression rule that only consumes an already-proven call.
function probeIndirect() {
  const viaAlias = install(before(), alias(), after());
  const viaMember = install(before(), holder.bail(), after());
  const viaNew = new bail();
  return [viaAlias, viaMember, viaNew];
}

// Caught: the exception never leaves this statement, so everything below
// still runs.
try {
  install(before(), bail(), after());
} catch {
  // handled
}

if (process.env.VT2_MODE === "fast") {
  module.exports = fastPath;
  // ==================================================================
  // THE CUTOFF. This is the entire case.
  //
  // `bail()` is in no privileged syntactic slot: not a bare statement,
  // not a declarator's whole initializer, not a class static field, not
  // any computed key, not a heritage clause. It is one ARGUMENT among
  // three.
  //
  // ECMAScript's EvaluateCall builds the argument list, left to right,
  // BEFORE the callee is entered. So `before()` runs, `bail()` throws,
  // `after()` never runs, `install` is never entered, and module
  // evaluation on this branch ends here. Nothing whatsoever about
  // `install` needs to be known for that to hold -- which is the point.
  // ==================================================================
  install(before(), bail(), after());
}

// Reached on every OTHER load, and on no load where the branch above was
// taken.
module.exports = slowPath;

void dangerousOp;
void guarded;
void chosen;
void mode;
void callback;
void withDefault;
void Holder;
void configure;
void probeIndirect;
void viaMaybe;
